        for (int i = 1; i <= n; i++) {
            cin >> a[i];
            ans = min(ans, (long long)i * a[i]);   // 初始时刻的排列权值 = min_j j*a_j
        }
        cout << ans << ' ';
        while (q--) {
            int x, y;
            cin >> x >> y;
            if (x != y) {
                swap(a[x], a[y]);
